BlockingQueue<Job> queue = new ArrayBlockingQueue<>(1000);   // the bound that matters
for (int i = 0; i < 500; i++) {
    Thread.ofVirtual().start(() -> {
        try {
            while (true) process(queue.take());   // blocks cheaply, unmounts
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();       // graceful shutdown
        }
    });
}
queue.put(job);                               // paced, not dropped
